actions.script:
const colors = {ready: 'positive', warning: 'warning', failed: 'negative'}
const states = {ready: ec.l10n.localize('Ready'), warning: ec.l10n.localize('Warning'), failed: ec.l10n.localize('Failed')}
archiveRows = Array.from(found?.archiveList || []).map(row => Object.assign({}, row, {
    stateText: states[row.state] || row.state, stateColor: colors[row.state] || 'grey-7',
    revisionText: row.revision ? row.revision.slice(0, 12) + (row.addressKind ? ' (' + row.addressKind + ')' : '') : '',
    detailText: [row.message].concat(Array.from(row.notes || [])).filter(text => text).join(' '),
    profileText: Array.from(row.profiles || []).map(profile => profile.profileName + (profile.enabled ? '' : ' (' + ec.l10n.localize('disabled') + ')')).join(', ')}))
profileRows = []
for (const row of archiveRows) for (const profile of Array.from(row.profiles || []))
    if (!profileRows.some(other => other.profileId === profile.profileId))
        profileRows.push(Object.assign({}, profile, {layerName: row.layerName, registered: !!row.revision,
            stateText: profile.enabled ? ec.l10n.localize('Enabled') : ec.l10n.localize('Disabled')}))
layerOptions = archiveRows.map(row => ({key: row.layerId, text: row.layerName}))
// the packaged local profile's two styles draw one extract: offered together while neither is registered
const unregistered = layerId => archiveRows.some(row => row.layerId === layerId && !row.revision)
registerDefaults = unregistered('LOCAL_PROTOMAPS_LIGHT') && unregistered('LOCAL_PROTOMAPS_DARK')
    ? {layerId: 'LOCAL_PROTOMAPS_LIGHT', alsoLayerIds: ['LOCAL_PROTOMAPS_DARK']} : {}
const limits = found?.limits || {}
limitsText = ec.l10n.localize('An upload is at most') + ' ' + (limits.maxUploadText || '?') + ' (max-upload); '
    + ec.l10n.localize('a Git LFS object at most') + ' ' + (limits.lfsMaxObjectText || '?') + ' (git-server@lfs-max-object-size); '
    + ec.l10n.localize('a git object that is not in LFS at most') + ' ' + (limits.gitMaxObjectText || '?') + ', '
    + ec.l10n.localize('and a map archive is never one') + '. '
    + ec.l10n.localize('A browser keeps the ranges it read for') + ' ' + (limits.pinnedMaxAge || '86400') + ' '
    + ec.l10n.localize('seconds (resource-facade@pinned-max-age): after a share is taken away it still shows them until then, and any other range is refused at once.')
